.example button {
  width: 100%;
  padding: 1.25rem;
  background: none;
  border: none;
  font-size: 1.1rem;
  font-weight: 600;
  text-align: left;
  color: #333;
  cursor: pointer;
  transition: background-color 0.2s ease;
  display: flex;
  justify-content: space-between;
  align-items: center;
  position: relative;
}

.example button::before {
  content: '';
  display: inline-block;
  width: 1.5rem;
  height: 1.5rem;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  clip-path: polygon(30% 40%, 50% 60%, 70% 40%);
  margin-left: 1rem;
  flex-shrink: 0;
  transition: transform 0.3s ease;
}

.example button[aria-expanded="true"]::before {
  transform: rotate(180deg);
}

.example button:hover {
  background-color: #f8f9fa;
}

.example button:focus {
  outline: 2px solid #667eea;
  outline-offset: -2px;
  background-color: #f0f2f8;
}

/* High contrast mode support */
@media (prefers-contrast: more) {
  .example button:focus {
    outline: 3px solid #333;
  }
}

/* Reduced motion support */
@media (prefers-reduced-motion: reduce) {
  .example button::before,
  .example button[aria-expanded="true"]::before,
  .example {
    transition: none;
  }
}

.details {
  padding: 1.25rem;
  border-top: 1px solid #e5e7eb;
  color: #555;
  background-color: #fafbfc;
}

.details p {
  margin-bottom: 0.75rem;
}

.details p:last-child {
  margin-bottom: 0;
}

.footer {
  background: #333;
  color: #ccc;
  text-align: center;
  padding: 2rem 1.5rem;
  font-size: 0.9rem;
  border-top: 4px solid #667eea;
}

/* Tablet and up */
@media (min-width: 768px) {
  .main {
    padding: 3rem 2rem;
  }

  .header {
    padding: 4rem 2rem;
  }

  .header h1 {
    font-size: 3rem;
  }

  .example button {
    padding: 1.5rem 2rem;
    font-size: 1.2rem;
  }

  .details {
    padding: 1.5rem 2rem;
  }
}

/* Mobile and down */
@media (max-width: 767px) {
  .header h1 {
    font-size: 1.8rem;
  }

  .subtitle {
    font-size: 1rem;
  }

  .example button::before {
    width: 1.25rem;
    height: 1.25rem;
    margin-left: 0.75rem;
  }
}

/* Ensure content stays visible without JavaScript */
.details[hidden] {
  display: none;
}

/* Smooth transitions for modern browsers */
@supports (animation: slide-down 0.3s ease-out) {
  .details {
    animation: slide-down 0.3s ease-out;
  }

  @keyframes slide-down {
    from {
      opacity: 0;
      transform: translateY(-10px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }
}
