  const buttons = document.querySelectorAll('.example button[aria-expanded]');

  buttons.forEach((button) => {
    // Initialize: collapse all panels on page load
    const panel = button.nextElementSibling;
    if (panel && panel.classList.contains('details')) {
      button.setAttribute('aria-expanded', 'false');
      panel.hidden = true;
    }

    // Handle click to toggle disclosure
    button.addEventListener('click', () => {
      const isExpanded = button.getAttribute('aria-expanded') === 'true';
      button.setAttribute('aria-expanded', String(!isExpanded));
      panel.hidden = isExpanded;
    });

    // Handle keyboard: Space and Enter activate the button (browser default)
    // Handle Escape to collapse (optional enhancement)
    button.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') {
        const isExpanded = button.getAttribute('aria-expanded') === 'true';
        if (isExpanded) {
          button.setAttribute('aria-expanded', 'false');
          panel.hidden = true;
          button.focus();
        }
      }
    });
  });
});

